# Code time: MVP RPG Sell Screen (clean, modular, minimal breakage)

## Step 1 — Create Sell overlay widget
### Create scene: `res://ui/widgets/SellMarkOverlay.tscn`
Node tree:
- `SellMarkOverlay` (Control) **anchors full rect**
  - `BG` (ColorRect) anchors full rect, color something like `Color(1, 0.55, 0.2, 0.18)`
  - `Check` (Label) text `✓`, top-left
  - `Price` (Label) bottom-right (small font)

Attach script: `res://ui/widgets/SellMarkOverlay.gd`

### New file: `res://ui/widgets/SellMarkOverlay.gd` (tabs)
```gdscript
extends Control
class_name SellMarkOverlay

@onready var bg: ColorRect = $BG
@onready var check: Label = $Check
@onready var price: Label = $Price

var _selected: bool = false

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	_set_selected(false)
	set_price(0)

func set_price(v: int) -> void:
	if price != null:
		price.text = str(v)

func set_selected(v: bool) -> void:
	_set_selected(v)

func _set_selected(v: bool) -> void:
	_selected = v
	if bg != null:
		bg.visible = v
	if check != null:
		check.visible = v
	if price != null:
		price.modulate = Color(1, 1, 1, 1.0 if v else 0.55)
```

---

## Step 2 — Create a simple Bag grid widget for the shop
(So we don’t fight BagUI’s “equip on click” behavior.)

### Create scene: `res://ui/widgets/ShopBagGrid.tscn`
- Root: `ShopBagGrid` (GridContainer)
  - Set `columns = 4`
  - (no children needed; it spawns slots)

Attach script: `res://ui/widgets/ShopBagGrid.gd`

### New file: `res://ui/widgets/ShopBagGrid.gd` (tabs)
```gdscript
extends GridContainer
class_name ShopBagGrid

signal slot_clicked(slot: int)

@export var slot_scene: PackedScene = preload("res://ui/bag/BagSlot.tscn")
@export var slot_count: int = 16

var _bag: BagInventory = null
var _slots: Array[BagSlot] = []

func _ready() -> void:
	columns = 4
	_build_slots()

func bind_bag(bag: BagInventory) -> void:
	if _bag != null and _bag.changed.is_connected(_refresh):
		_bag.changed.disconnect(_refresh)

	_bag = bag

	if _bag != null and not _bag.changed.is_connected(_refresh):
		_bag.changed.connect(_refresh)

	_refresh()

func get_slot_control(i: int) -> Control:
	if i < 0 or i >= _slots.size():
		return null
	return _slots[i] as Control

func _build_slots() -> void:
	for c in get_children():
		c.queue_free()

	_slots.clear()

	for i in range(slot_count):
		var s: BagSlot = slot_scene.instantiate() as BagSlot
		add_child(s)
		_slots.append(s)

		# We use equip_requested as "clicked with index" (safe for shop use)
		var cb := Callable(self, "_on_slot_equip_requested").bind(i)
		if not s.equip_requested.is_connected(cb):
			s.equip_requested.connect(cb)

	_refresh()

func _on_slot_equip_requested(_slot_index: int, forced_i: int) -> void:
	slot_clicked.emit(forced_i)

func _refresh() -> void:
	if _bag != null:
		_bag._ensure_size()

	for i in range(_slots.size()):
		var inst: ItemInstance = null
		if _bag != null and i < _bag.slots.size():
			inst = _bag.slots[i]
		_slots[i].set_stack(inst, i, false, false)
```

