## Step 4 — Replace `HubShop.gd` with the new controller
**File:** `res://ui/screens/HubShop.gd` (tabs)  
Replace the whole file with this:

```gdscript
extends Control

@onready var title: Label = $Root/HBox/Left/Margin/VBox/Title
@onready var info: Label = $Root/HBox/Left/Margin/VBox/Info
@onready var cart: Label = $Root/HBox/Left/Margin/VBox/Cart
@onready var hover: Label = $Root/HBox/Left/Margin/VBox/Hover

@onready var btn_mark_all_bag: Button = $Root/HBox/Left/Margin/VBox/ButtonsRow/MarkAllBag
@onready var btn_mark_neg: Button = $Root/HBox/Left/Margin/VBox/ButtonsRow/MarkNEG
@onready var btn_clear: Button = $Root/HBox/Left/Margin/VBox/ButtonsRow/Clear

@onready var chk_include_equipped: CheckBox = $Root/HBox/Left/Margin/VBox/IncludeEquipped
@onready var btn_sell_selected: Button = $Root/HBox/Left/Margin/VBox/SellSelected
@onready var btn_continue: Button = $Root/HBox/Left/Margin/VBox/Continue
@onready var btn_menu: Button = $Root/HBox/Left/Margin/VBox/Menu

@onready var inv_bar: InventoryBar = $Root/HBox/Equipped/Margin/VBox/InventoryBar
@onready var bag_grid: ShopBagGrid = $Root/HBox/Backpack/Margin/VBox/BagGrid

@onready var confirm_sell: ConfirmationDialog = $ConfirmSell

@export var sell_overlay_scene: PackedScene = preload("res://ui/widgets/SellMarkOverlay.tscn")

var _sel_inv: Dictionary = {} # int -> true
var _sel_bag: Dictionary = {} # int -> true

var _inv_ov: Array[SellMarkOverlay] = []
var _bag_ov: Array[SellMarkOverlay] = []

func _ready() -> void:
	get_tree().paused = false
	process_mode = Node.PROCESS_MODE_ALWAYS

	# Mark resume target as Hub/Shop
	if SaveManager != null and SaveManager.current_save != null:
		SaveManager.current_save.attempt_resume_scene = Global.PATH_HUB_SHOP
	if Global != null:
		Global.save_current_profile()

	# Bind data
	inv_bar.allow_double_click_eject_always = false
	inv_bar.set_management_mode(false)
	inv_bar.bind_inventory(Global.run_inventory)
	bag_grid.bind_bag(Global.run_bag)

	# Wire clicks
	if not inv_bar.slot_clicked.is_connected(_on_inv_slot_clicked):
		inv_bar.slot_clicked.connect(_on_inv_slot_clicked)
	if not bag_grid.slot_clicked.is_connected(_on_bag_slot_clicked):
		bag_grid.slot_clicked.connect(_on_bag_slot_clicked)

	# Build overlays + hover hookups
	_build_overlays()

	# Buttons
	btn_mark_all_bag.pressed.connect(_mark_all_bag)
	btn_mark_neg.pressed.connect(_mark_negatives)
	btn_clear.pressed.connect(_clear_selection)
	btn_sell_selected.pressed.connect(_sell_selected_pressed)
	btn_continue.pressed.connect(_start_next_segment)
	btn_menu.pressed.connect(_to_menu)

	confirm_sell.confirmed.connect(_perform_sale)

	_refresh_info()
	_refresh_cart()

func _to_menu() -> void:
	if Global != null:
		Global.save_current_profile()
	Global.goto_main_menu()

func _refresh_info() -> void:
	var seg := (Global.attempt_segment if Global != null else 1)
	var fol := (Global.followers if Global != null else 0)

	var extra := ""
	if Global != null and Global.pending_augment_pick:
		extra += "\nReward: Augment pick available"
	if Global != null and Global.pending_big_choice:
		extra += "\nReward: Major choice pending (Segment 5 milestone)"

	title.text = "Interlude"
	info.text = "Next Segment: %d\nFollowers: %d%s" % [seg, fol, extra]

func _build_overlays() -> void:
	_inv_ov.clear()
	_bag_ov.clear()

	# Inventory overlays
	for i in range(Inventory.SLOT_COUNT):
		var c: Control = inv_bar.get_slot_control(i)
		if c == null:
			_inv_ov.append(null)
			continue

		var ov: SellMarkOverlay = sell_overlay_scene.instantiate() as SellMarkOverlay
		c.add_child(ov)
		ov.set_anchors_preset(Control.PRESET_FULL_RECT)
		ov.z_index = 50
		ov.z_as_relative = false
		_inv_ov.append(ov)

		# Hover preview
		var ent := Callable(self, "_on_hover_inv").bind(i)
		var ext := Callable(self, "_on_hover_clear")
		if not c.mouse_entered.is_connected(ent):
			c.mouse_entered.connect(ent)
		if not c.mouse_exited.is_connected(ext):
			c.mouse_exited.connect(ext)

	# Bag overlays
	for j in range(BagInventory.SLOT_COUNT):
		var cb: Control = bag_grid.get_slot_control(j)
		if cb == null:
			_bag_ov.append(null)
			continue

		var ovb: SellMarkOverlay = sell_overlay_scene.instantiate() as SellMarkOverlay
		cb.add_child(ovb)
		ovb.set_anchors_preset(Control.PRESET_FULL_RECT)
		ovb.z_index = 50
		ovb.z_as_relative = false
		_bag_ov.append(ovb)

		var ent2 := Callable(self, "_on_hover_bag").bind(j)
		var ext2 := Callable(self, "_on_hover_clear")
		if not cb.mouse_entered.is_connected(ent2):
			cb.mouse_entered.connect(ent2)
		if not cb.mouse_exited.is_connected(ext2):
			cb.mouse_exited.connect(ext2)

	_refresh_overlays()

func _refresh_overlays() -> void:
	# Inventory
	for i in range(_inv_ov.size()):
		var ov: SellMarkOverlay = _inv_ov[i]
		if ov == null:
			continue
		var inst: ItemInstance = Global.run_inventory.get_at(i) if Global.run_inventory != null else null
		var price: int = (Global.compute_sell_value(inst) if inst != null else 0)
		ov.set_price(price)
		ov.set_selected(_sel_inv.has(i))

	# Bag
	for j in range(_bag_ov.size()):
		var ovb: SellMarkOverlay = _bag_ov[j]
		if ovb == null:
			continue
		var inst2: ItemInstance = (Global.run_bag.slots[j] if Global.run_bag != null and j < Global.run_bag.slots.size() else null)
		var price2: int = (Global.compute_sell_value(inst2) if inst2 != null else 0)
		ovb.set_price(price2)
		ovb.set_selected(_sel_bag.has(j))

func _on_inv_slot_clicked(slot: int, _button: int, _double: bool, _shift: bool) -> void:
	if Global.run_inventory == null:
		return
	if Global.run_inventory.get_at(slot) == null:
		return
	if _sel_inv.has(slot):
		_sel_inv.erase(slot)
	else:
		_sel_inv[slot] = true
	_refresh_overlays()
	_refresh_cart()

func _on_bag_slot_clicked(slot: int) -> void:
	if Global.run_bag == null:
		return
	if slot < 0 or slot >= Global.run_bag.slots.size():
		return
	if Global.run_bag.slots[slot] == null:
		return
	if _sel_bag.has(slot):
		_sel_bag.erase(slot)
	else:
		_sel_bag[slot] = true
	_refresh_overlays()
	_refresh_cart()

func _mark_all_bag() -> void:
	_sel_bag.clear()
	if Global.run_bag != null:
		for i in range(Global.run_bag.slots.size()):
			if Global.run_bag.slots[i] != null:
				_sel_bag[i] = true
	_refresh_overlays()
	_refresh_cart()

func _mark_negatives() -> void:
	_sel_bag.clear()
	_sel_inv.clear()

	# Bag negatives
	if Global.run_bag != null:
		for i in range(Global.run_bag.slots.size()):
			var it: ItemInstance = Global.run_bag.slots[i]
			if it != null and it.polarity == ItemInstance.Polarity.NEG:
				_sel_bag[i] = true

	# Equipped negatives only if enabled
	if chk_include_equipped.button_pressed and Global.run_inventory != null:
		for j in range(Inventory.SLOT_COUNT):
			var it2: ItemInstance = Global.run_inventory.get_at(j)
			if it2 != null and it2.polarity == ItemInstance.Polarity.NEG:
				_sel_inv[j] = true

	_refresh_overlays()
	_refresh_cart()

func _clear_selection() -> void:
	_sel_bag.clear()
	_sel_inv.clear()
	_refresh_overlays()
	_refresh_cart()

func _compute_total_value() -> int:
	var total: int = 0

	if Global.run_inventory != null:
		for k in _sel_inv.keys():
			var idx: int = int(k)
			var inst: ItemInstance = Global.run_inventory.get_at(idx)
			if inst != null:
				total += Global.compute_sell_value(inst)

	if Global.run_bag != null:
		for k2 in _sel_bag.keys():
			var idx2: int = int(k2)
			if idx2 >= 0 and idx2 < Global.run_bag.slots.size():
				var inst2: ItemInstance = Global.run_bag.slots[idx2]
				if inst2 != null:
					total += Global.compute_sell_value(inst2)

	return total

func _compute_count_selected() -> int:
	return _sel_inv.size() + _sel_bag.size()

func _refresh_cart() -> void:
	var n: int = _compute_count_selected()
	var total: int = _compute_total_value()
	cart.text = "Cart: %d items\nValue: %d followers" % [n, total]

func _sell_selected_pressed() -> void:
	var n: int = _compute_count_selected()
	var total: int = _compute_total_value()
	if n <= 0 or total <= 0:
		return

	confirm_sell.dialog_text = "Sell %d item(s) for %d followers?" % [n, total]
	confirm_sell.popup_centered()

func _perform_sale() -> void:
	var gained: int = 0

	# Sell equipped first (stable indices)
	if Global.run_inventory != null:
		for k in _sel_inv.keys():
			var idx: int = int(k)
			var inst: ItemInstance = Global.run_inventory.get_at(idx)
			if inst != null:
				gained += Global.compute_sell_value(inst)
				Global.run_inventory.remove_at(idx)

	# Sell bag
	if Global.run_bag != null:
		for k2 in _sel_bag.keys():
			var idx2: int = int(k2)
			if idx2 >= 0 and idx2 < Global.run_bag.slots.size():
				var inst2: ItemInstance = Global.run_bag.slots[idx2]
				if inst2 != null:
					gained += Global.compute_sell_value(inst2)
					Global.run_bag.remove_at(idx2)

	_clear_selection()

	if Global != null:
		Global.add_followers(gained)
		Global.save_current_profile()

	_refresh_info()
	_refresh_overlays()
	_refresh_cart()

func _on_hover_inv(slot: int) -> void:
	if Global.run_inventory == null:
		return
	var inst: ItemInstance = Global.run_inventory.get_at(slot)
	_set_hover_from_item(inst)

func _on_hover_bag(slot: int) -> void:
	if Global.run_bag == null or slot < 0 or slot >= Global.run_bag.slots.size():
		return
	var inst: ItemInstance = Global.run_bag.slots[slot]
	_set_hover_from_item(inst)

func _set_hover_from_item(inst: ItemInstance) -> void:
	if inst == null or inst.data == null:
		hover.text = ""
		return
	var v: int = Global.compute_sell_value(inst)
	var pol := ("NEG" if inst.polarity == ItemInstance.Polarity.NEG else "POS")
	hover.text = "%s  (R%d %s)\nSell: %d" % [inst.data.display_name, int(inst.rarity), pol, v]

func _on_hover_clear() -> void:
	hover.text = ""

func _start_next_segment() -> void:
	Global.attempt_deaths_this_segment = 0
	Global.attempt_checkpoint_pos = Vector2.INF

	if SaveManager != null and SaveManager.current_save != null:
		SaveManager.current_save.attempt_resume_scene = Global.PATH_GAME

	Global.save_current_profile()
	Global.goto_game()
```

---

## What you’ll get immediately
- Click-to-mark selling (bag + optional equipped)
- Per-slot prices (always visible, bright when selected)
- Cart total + confirm dialog
- Mark All Bag / Mark NEG / Clear
- Hover preview of sell value

## Easy upgrades after MVP
- “Lock item” star toggle
- Filter buttons (rarity tiers / only POS / only NEG)
- Show an actual follower icon next to price
- Sell categories (sell all commons, sell all negatives, etc.)

If you answer those two little questions (NEG-only vs more rules, and whether you want “Lock”), I’ll tailor the next pass to avoid repainting UI later.
